<template>
  <ManagementLayout>
    <div class="page-heading"><div><p class="eyebrow">YOUR PLACES, BEAUTIFULLY PRESENTED</p><h1>Restaurants</h1><p>A home for every place you’re proud to share.</p></div><router-link to="/add" class="button primary"><AppIcon name="plus" /> Add restaurant</router-link></div>
    <p v-if="error" class="notice error" role="alert">{{ error }} <button class="text-button" @click="load">Try again</button></p>
    <section class="panel table-panel"><div class="table-toolbar"><div><h2>Your collection <span class="count-badge">{{ restaurants.length }}</span></h2><p>Keep your restaurant details fresh and welcoming.</p></div><label class="search-field"><AppIcon name="search" /><input v-model="search" placeholder="Search restaurants…" aria-label="Search restaurants" /></label></div>
      <p v-if="loading" class="loading-state">Loading your restaurants…</p>
      <div v-else-if="!error && !filtered.length" class="empty-state"><span class="icon-tile large"><AppIcon name="restaurant" /></span><h2>{{ search ? 'No places found.' : 'Every great restaurant has a story.' }}</h2><p>{{ search ? 'Try a different name or address.' : 'Start yours by creating your first listing.' }}</p><router-link v-if="!search" to="/add" class="button primary">Add your first restaurant <AppIcon name="arrow" /></router-link></div>
      <div v-else-if="filtered.length" class="table-scroll"><table class="data-table"><thead><tr><th>Restaurant</th><th>Location</th><th>Contact</th><th>Visibility</th><th class="align-right">Actions</th></tr></thead><tbody><tr v-for="restaurant in filtered" :key="restaurant.id"><td><div class="table-identity"><img :src="restaurant.image || '/images/restaurant-placeholder.svg'" :alt="restaurant.name" /><div><strong>{{ restaurant.name }}</strong><small>Restaurant #{{ restaurant.id }}</small></div></div></td><td><span class="cell-address">{{ restaurant.address }}</span></td><td>{{ restaurant.contact }}</td><td><span class="pill"><span class="status-dot"></span> Public listing</span></td><td><div class="row-actions"><router-link :to="`/restaurant/${restaurant.id}/menu`" class="icon-button" :aria-label="`View ${restaurant.name} menu`"><AppIcon name="external" /></router-link><router-link :to="`/update/${restaurant.id}`" class="icon-button" :aria-label="`Edit ${restaurant.name}`"><AppIcon name="edit" /></router-link><button class="icon-button delete-action" :aria-label="`Delete ${restaurant.name}`" @click="target=restaurant"><AppIcon name="trash" /></button></div></td></tr></tbody></table></div>
      <div v-if="filtered.length" class="table-bottom">Showing {{ filtered.length }} of {{ restaurants.length }} restaurants <span>Only your listings appear here.</span></div>
    </section>
    <ConfirmDialog :open="Boolean(target)" title="Remove this restaurant?" :message="target ? `${target.name} and its menu items will be deleted.` : ''" :busy="deleting" @cancel="target=null" @confirm="remove" />
  </ManagementLayout>
</template>
<script>
import ManagementLayout from '../shared/ManagementLayout.vue';import AppIcon from '../shared/AppIcon.vue';import ConfirmDialog from '../shared/ConfirmDialog.vue';import http from '../../services/http';
export default { components:{ManagementLayout,AppIcon,ConfirmDialog},data:()=>({restaurants:[],search:'',loading:true,error:'',target:null,deleting:false}),computed:{filtered(){const q=this.search.trim().toLowerCase();return this.restaurants.filter(item=>[item.name,item.address,item.contact].join(' ').toLowerCase().includes(q));}},mounted(){this.load();},methods:{async load(){this.error='';this.loading=true;try{this.restaurants=(await http.get('/restaurant?mine=1')).data;}catch(error){this.error=error.response?.data?.error||'We couldn’t load your restaurants.';}finally{this.loading=false;}},async remove(){if(!this.target||this.deleting)return;this.deleting=true;try{await http.delete(`/restaurant/${this.target.id}`);this.target=null;await this.load();}catch(error){this.target=null;this.error=error.response?.data?.error||'We couldn’t delete this restaurant.';}finally{this.deleting=false;}}}};
</script>
